insert into public.angelcare360_permissions(permission_key,domain_key,action_key,label,description,risk_level,status) values
('angelcare360.securite.view','securite','view','Voir les utilisateurs et accès','Consulter les rôles, périmètres, demandes et revues de son établissement.','medium','active'),
('angelcare360.securite.configure','securite','configure','Configurer les accès de l’établissement','Inviter, attribuer des rôles approuvés et maintenir les périmètres.','high','active'),
('angelcare360.securite.approve','securite','approve','Valider les accès sensibles','Approuver les rôles, délégations, urgences et revues à fort impact.','critical','active'),
('angelcare360.securite.audit','securite','audit','Auditer les accès','Examiner les versions, décisions et traces d’accès.','high','active') on conflict(permission_key) do update set label=excluded.label,description=excluded.description,risk_level=excluded.risk_level,status=excluded.status,updated_at=now();
