begin;
create extension if not exists pgcrypto;
create table if not exists public.angelcare360_access_invitations(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,person_id uuid,email text not null,role_id uuid references public.angelcare360_roles(id) on delete set null,scope_json jsonb not null default '{}',state text not null default 'prepared',starts_at timestamptz,expires_at timestamptz,sent_at timestamptz not null default now(),activated_at timestamptz,cancelled_at timestamptz,invited_by uuid references public.app_users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare360_access_role_versions(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,role_id uuid not null references public.angelcare360_roles(id) on delete cascade,version_number integer not null,label text not null,description text,permission_keys jsonb not null default '[]',scope_policy jsonb not null default '{}',state text not null default 'draft',change_reason text,requested_at timestamptz,published_by uuid references public.app_users(id) on delete set null,published_at timestamptz,replaced_at timestamptz,created_by uuid references public.app_users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(role_id,version_number));
create table if not exists public.angelcare360_access_requests(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,requester_user_id uuid references public.app_users(id) on delete set null,requester_label text,requested_role_id uuid references public.angelcare360_roles(id) on delete set null,requested_role_label text,requested_permission_keys jsonb not null default '[]',scope_label text not null default 'Établissement',reason text not null,starts_at timestamptz,ends_at timestamptz,sensitive_impact text,state text not null default 'pending',risk_score integer not null default 0,reviewer_id uuid references public.app_users(id) on delete set null,reviewer_label text,decision_reason text,reviewed_by uuid references public.app_users(id) on delete set null,reviewed_at timestamptz,created_by uuid references public.app_users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare360_temporary_access_grants(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,app_user_id uuid not null references public.app_users(id) on delete cascade,role_id uuid references public.angelcare360_roles(id) on delete set null,permission_keys jsonb not null default '[]',scope_json jsonb not null default '{}',reason text not null,starts_at timestamptz not null,ends_at timestamptz not null,state text not null default 'pending',approved_by uuid references public.app_users(id) on delete set null,approved_at timestamptz,ended_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(ends_at>starts_at));
create table if not exists public.angelcare360_access_delegations(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,delegator_user_id uuid not null references public.app_users(id) on delete restrict,delegate_user_id uuid not null references public.app_users(id) on delete restrict,role_id uuid references public.angelcare360_roles(id) on delete set null,operation_keys jsonb not null default '[]',scope_label text not null default 'Établissement',reason text not null,starts_at timestamptz not null,ends_at timestamptz,state text not null default 'draft',approval_label text,requested_at timestamptz,approved_by uuid references public.app_users(id) on delete set null,approved_at timestamptz,activated_at timestamptz,ended_at timestamptz,usage_count integer not null default 0,created_by uuid references public.app_users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(ends_at is null or ends_at>starts_at));
create table if not exists public.angelcare360_sensitive_access_grants(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,app_user_id uuid not null references public.app_users(id) on delete cascade,category_key text not null,category_label text not null,purpose text not null,scope_label text not null,starts_at timestamptz,ends_at timestamptz,state text not null default 'pending',approval_label text,requested_by uuid references public.app_users(id) on delete set null,approved_by uuid references public.app_users(id) on delete set null,approved_at timestamptz,last_reviewed_at timestamptz,next_review_at timestamptz,reviewed_by uuid references public.app_users(id) on delete set null,revoked_by uuid references public.app_users(id) on delete set null,revoked_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare360_access_review_campaigns(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,name text not null,scope_label text not null,scope_json jsonb not null default '{}',reviewer_id uuid references public.app_users(id) on delete set null,reviewer_label text,due_at timestamptz,state text not null default 'draft',user_count integer not null default 0,completed_by uuid references public.app_users(id) on delete set null,completed_at timestamptz,created_by uuid references public.app_users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare360_access_review_decisions(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,review_id uuid not null references public.angelcare360_access_review_campaigns(id) on delete cascade,app_user_id uuid not null references public.app_users(id) on delete cascade,decision text not null,reason text,decided_by uuid references public.app_users(id) on delete set null,decided_at timestamptz not null default now(),result_json jsonb not null default '{}',unique(review_id,app_user_id));
create table if not exists public.angelcare360_emergency_access_events(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,app_user_id uuid not null references public.app_users(id) on delete cascade,operation_keys jsonb not null default '[]',scope_json jsonb not null default '{}',reason text not null,starts_at timestamptz not null,ends_at timestamptz not null,state text not null default 'pending',requested_by uuid references public.app_users(id) on delete set null,approved_by uuid references public.app_users(id) on delete set null,approved_at timestamptz,activated_at timestamptz,revoked_by uuid references public.app_users(id) on delete set null,revoked_at timestamptz,reviewed_by uuid references public.app_users(id) on delete set null,reviewed_at timestamptz,review_notes text,created_at timestamptz not null default now(),check(ends_at>starts_at));
create table if not exists public.angelcare360_access_separation_findings(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,fingerprint text not null,app_user_id uuid references public.app_users(id) on delete cascade,rule_key text not null,conflicting_operations jsonb not null default '[]',severity text not null default 'high',state text not null default 'open',exception_id uuid,detected_at timestamptz not null default now(),resolved_at timestamptz,unique(school_id,fingerprint));
create table if not exists public.angelcare360_access_issues(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,fingerprint text not null,category text not null,title text not null,detail text not null,consequence text,app_user_id uuid references public.app_users(id) on delete set null,user_label text,role_id uuid references public.angelcare360_roles(id) on delete set null,role_label text,severity text not null default 'warning',state text not null default 'open',owner_id uuid references public.app_users(id) on delete set null,owner_label text,due_at timestamptz,recommended_action_key text,recommended_action_label text,resolution_reason text,resolved_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(school_id,fingerprint));
create table if not exists public.angelcare360_access_tasks(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,app_user_id uuid references public.app_users(id) on delete set null,issue_id uuid references public.angelcare360_access_issues(id) on delete set null,title text not null,detail text,owner_id uuid references public.app_users(id) on delete set null,owner_label text,due_at timestamptz,state text not null default 'open',completed_at timestamptz,created_by uuid references public.app_users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare360_access_notes(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,entity_type text not null,entity_id uuid,note text not null,created_by uuid references public.app_users(id) on delete set null,created_at timestamptz not null default now());
create table if not exists public.angelcare360_access_evidence_requests(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,app_user_id uuid references public.app_users(id) on delete set null,category_key text not null,request_text text not null,state text not null default 'requested',requested_by uuid references public.app_users(id) on delete set null,due_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.angelcare360_access_topup_requests(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,requested_quantity integer not null check(requested_quantity>0),meter_key text not null,package_version_id uuid,state text not null default 'requested',source_context jsonb not null default '{}',requested_by uuid references public.app_users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare360_access_history(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,entity_type text not null,entity_id uuid,action_key text not null,label text not null,detail text,actor_id uuid references public.app_users(id) on delete set null,actor_label text,state text not null default 'recorded',created_at timestamptz not null default now());
create table if not exists public.angelcare360_access_action_receipts(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,action_key text not null,idempotency_key text not null,result_json jsonb not null default '{}',created_at timestamptz not null default now(),unique(school_id,action_key,idempotency_key));
create index if not exists ac360_access_invites_idx on public.angelcare360_access_invitations(school_id,state,expires_at);
create index if not exists ac360_access_requests_idx on public.angelcare360_access_requests(school_id,state,created_at desc);
create index if not exists ac360_access_delegations_idx on public.angelcare360_access_delegations(school_id,state,starts_at,ends_at);
create index if not exists ac360_sensitive_access_idx on public.angelcare360_sensitive_access_grants(school_id,state,next_review_at);
create index if not exists ac360_access_reviews_idx on public.angelcare360_access_review_campaigns(school_id,state,due_at);
create index if not exists ac360_access_issues_idx on public.angelcare360_access_issues(school_id,state,severity,due_at);
create index if not exists ac360_access_history_idx on public.angelcare360_access_history(school_id,created_at desc);
do $$ declare t text; begin foreach t in array array['angelcare360_access_invitations','angelcare360_access_role_versions','angelcare360_access_requests','angelcare360_temporary_access_grants','angelcare360_access_delegations','angelcare360_sensitive_access_grants','angelcare360_access_review_campaigns','angelcare360_access_review_decisions','angelcare360_emergency_access_events','angelcare360_access_separation_findings','angelcare360_access_issues','angelcare360_access_tasks','angelcare360_access_notes','angelcare360_access_evidence_requests','angelcare360_access_topup_requests','angelcare360_access_history','angelcare360_access_action_receipts'] loop execute format('alter table public.%I enable row level security',t); execute format('revoke insert,update,delete on public.%I from anon,authenticated',t); end loop; end $$;

on conflict(operation_key) do update set route_path=excluded.route_path,feature_key=excluded.feature_key,operation_name=excluded.operation_name,permission_key=excluded.permission_key,audit_event=excluded.audit_event,mutation_endpoints=excluded.mutation_endpoints,source_confidence=excluded.source_confidence,status=excluded.status,updated_at=now();
commit;
